function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key)||JSON.stringify(fallback))}catch{return fallback}}
function writeStore(key,value){localStorage.setItem(key,JSON.stringify(value))}
function universePageHead(kicker,title,copy,extra=''){return `<header class="universe-head"><div><div class="kicker">${esc(kicker)}</div><h1>${title}</h1></div><div class="universe-head-copy"><p>${copy}</p>${extra}</div></header>`}
function systemCards(limit=999){return BABEL_SYSTEMS.slice(0,limit).map(s=>`<article class="system-index-card" data-go="${esc(s.route)}"><div class="system-index-top"><span>${esc(s.n)}</span><span>${esc(s.kind)}</span></div><h3>${esc(s.name)}</h3><p>${esc(s.desc)}</p><div class="system-open">Open system ↗</div></article>`).join('')}
function bindGo(){document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>route(x.dataset.go));wireRoutes()}
function evidenceKey(label=''){const x=label.toLowerCase();if(/established|mathematical|documented phenomenon|practical/.test(x))return'known';if(/historical|cultural|religious|folklore|literary/.test(x))return'culture';if(/disputed|unverified|unsupported|paranormal|speculat/.test(x))return'uncertain';return'open'}
function safeLink(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return'#'}}
function shortHost(url){try{return new URL(url).hostname.replace(/^www\./,'')}catch{return''}}
function copyText(text){navigator.clipboard?.writeText(text).then(()=>toast('Copied')).catch(()=>toast('Copy failed'))}

