async function researchPage(){
  setTitle('Research');
  const q=new URLSearchParams(location.search).get('q')||'';
  app.innerHTML=`<div class="page">${universePageHead('System 01 / live sources','Research of Babel','Search the local index and several public research sources in parallel. Results are pointers for investigation, not automatic endorsements of what a source says.')}
    <form class="research-console" id="researchForm"><input id="researchQ" value="${esc(q)}" placeholder="Research anything"><button>Search sources</button></form>
    <div class="research-layout"><aside class="research-aside"><div class="kicker">SOURCE LAYERS</div><button data-layer="all" class="active">All sources</button><button data-layer="Reference">Reference</button><button data-layer="Scholarship">Scholarship</button><button data-layer="Archive">Archive</button><button data-layer="Discussion signal">Discussion signals</button><hr><a href="/sources" data-route>Source Atlas →</a><a href="/web-network" data-route>Map a website →</a></aside><section id="researchResults" class="research-results"><div class="research-empty">Enter a subject. Babel will combine live public pointers with a stable local topic branch.</div></section></div>
  </div>`;
  let results=[];let layer='all';
  const draw=()=>{const box=document.querySelector('#researchResults');const show=results.filter(r=>layer==='all'||r.kind===layer);box.innerHTML=show.length?show.map((r,i)=>`<article class="source-result"><div class="source-result-meta"><span>${String(i+1).padStart(2,'0')}</span><span>${esc(r.source)} · ${esc(r.kind)}</span></div>${r.image?`<img src="${esc(r.image)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:''}<div><h3><a href="/reader?url=${encodeURIComponent(r.url)}" data-route>${esc(r.title)}</a></h3><p>${esc(r.snippet||'Open source result.')}</p><div class="source-host">${esc(shortHost(r.url))}${r.year?` · ${esc(r.year)}`:''}</div></div></article>`).join(''):`<div class="research-empty">No results in this layer.</div>`};
  const run=async query=>{if(!query)return;const box=document.querySelector('#researchResults');box.innerHTML=`<div class="research-empty">Searching live source layers for “${esc(query)}”...</div>`;history.replaceState({},'',`/research?q=${encodeURIComponent(query)}`);try{const [live]=await Promise.all([json(`/api/research?q=${encodeURIComponent(query)}`),openTopicSilent(query)]);results=live.sources||[];draw();const local=localTopics()[slug(query)]||state.current;const intro=document.createElement('article');intro.className='research-branch';intro.innerHTML=`<div><div class="kicker">BABEL BRANCH</div><h3>${esc(local?.title||query)}</h3><p>${esc(local?.dek||'A stable local index branch for this subject.')}</p></div><button id="openResearchBranch">Open branch →</button>`;box.prepend(intro);document.querySelector('#openResearchBranch').onclick=()=>route(`/topic/${slug(query)}`)}catch(e){box.innerHTML=`<div class="research-empty error">${esc(e.message)}</div>`}};
  document.querySelector('#researchForm').onsubmit=e=>{e.preventDefault();run(document.querySelector('#researchQ').value.trim())};
  document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{layer=b.dataset.layer;document.querySelectorAll('[data-layer]').forEach(x=>x.classList.toggle('active',x===b));draw()});
  wireRoutes(); if(q)run(q);
}

async function openTopicSilent(q){
  try{const s=slug(q);const local=localTopics()[s];if(local){state.current=local;return local}const d=await json(`/api/topic?q=${encodeURIComponent(q)}`);state.current=d.topic;if(d.persistence!=='shared')saveLocal(d.topic);return d.topic}catch{return null}
}

function renderWebGraph(data){
  const stage=document.querySelector('#webGraphStage');if(!stage)return;
  const links=(data.links||[]).slice(0,42);const width=900,height=590,cx=450,cy=295,r=225;
  const pts=links.map((x,i)=>{const a=(Math.PI*2*i/Math.max(1,links.length))-Math.PI/2;return {...x,x:cx+Math.cos(a)*r*(.82+(i%3)*.08),y:cy+Math.sin(a)*r*(.82+(i%3)*.08)}});
  stage.innerHTML=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Outgoing link graph"><g class="web-lines">${pts.map(p=>`<line x1="${cx}" y1="${cy}" x2="${p.x}" y2="${p.y}"></line>`).join('')}</g><g><circle class="web-root" cx="${cx}" cy="${cy}" r="49"></circle><text class="web-root-text" x="${cx}" y="${cy-5}" text-anchor="middle">${esc(data.root.host.slice(0,20))}</text><text class="web-root-sub" x="${cx}" y="${cy+13}" text-anchor="middle">ROOT</text>${pts.map((p,i)=>`<g class="web-node" data-weburl="${esc(p.url)}"><circle cx="${p.x}" cy="${p.y}" r="${p.sameSite?12:16}"></circle><text x="${p.x}" y="${p.y+29}" text-anchor="middle">${esc(p.host.slice(0,22))}</text></g>`).join('')}</g></svg>`;
  stage.querySelectorAll('[data-weburl]').forEach(n=>n.onclick=()=>mapWeb(n.dataset.weburl));
}
async function mapWeb(url){
  const out=document.querySelector('#webMapInfo');const stage=document.querySelector('#webGraphStage');if(!out||!stage)return;
  out.innerHTML=`<div class="kicker">MAPPING</div><h3>${esc(url)}</h3><p>Following public HTML links...</p>`;
  try{const d=await json(`/api/webgraph?url=${encodeURIComponent(url)}`);webTrail.unshift(d.root);renderWebGraph(d);out.innerHTML=`<div class="kicker">CURRENT PAGE</div><h3>${esc(d.root.title||d.root.host)}</h3><p>${esc(d.root.description||d.root.url)}</p><dl><div><dt>Links</dt><dd>${d.counts.links}</dd></div><div><dt>Domains</dt><dd>${d.counts.hosts}</dd></div><div><dt>External</dt><dd>${d.counts.external}</dd></div></dl><a href="/reader?url=${encodeURIComponent(d.root.url)}" data-route>Read in Babel →</a>`;document.querySelector('#webTrail').innerHTML=webTrail.map(x=>`<button data-trail="${esc(x.url)}">${esc(x.host)}</button>`).join('');document.querySelectorAll('[data-trail]').forEach(b=>b.onclick=()=>mapWeb(b.dataset.trail))}catch(e){stage.innerHTML=`<div class="webgraph-error">${esc(e.message)}</div>`;out.innerHTML=`<div class="kicker">MAP ERROR</div><h3>Could not map that page</h3><p>${esc(e.message)}</p>`}
}
